    nachrichtenWoche: nachricht('Wähle höchstens 5 der folgenden Meldungen der letzten Woche, die man als IT-Verantwortlicher unbedingt wissen sollte, und fasse jede in einem Satz zusammen.', woche),
  },
}];

const termine = $('Termine auswerten').first().json;
const daten = $('Daten aufbereiten').first().json;
const bereinigen = (wert) => String(wert || '').replace(/```[a-z]*\n?/gi, '').replace(/@(channel|all|here)\b/gi, '@​$1').trim().slice(0, 3000);
const ki = (knoten) => {
  try {
    const j = $(knoten).first().json;
    const inhalt = j && j.message && j.message.content ? bereinigen(j.message.content) : '';
    return /^\s*[-*]\s/m.test(inhalt) ? inhalt : '';
  } catch (e) {
    return '';
  }
};
const liste = (eintraege, max) => eintraege.slice(0, max).map((e) => `- [${e.titel}](${e.link}) _(${e.quelle})_`).join('\n');
const sicherheitKi = daten.anzahlSicherheit > 0 ? ki('KI Sicherheit') : '';
const wocheKi = daten.anzahlWoche > 0 ? ki('KI Wochennews') : '';
const sicherheit = daten.anzahlSicherheit === 0 ? '- Keine neuen Meldungen in den letzten 48 Stunden.' : sicherheitKi || `${liste(daten.sicherheit, 5)}\n_Ohne KI-Zusammenfassung (Ollama-PC nicht erreichbar)._`;
const woche = daten.anzahlWoche === 0 ? '- Keine weiteren Meldungen.' : wocheKi || `${liste(daten.woche, 5)}\n_Ohne KI-Zusammenfassung (Ollama-PC nicht erreichbar)._`;
const WMO = (code) => {
  if (code === 0) return '\u2600\uFE0F klar';
  if (code === 1) return '\u{1F324}\uFE0F \u00FCberwiegend klar';
  if (code === 2) return '\u26C5 teils bew\u00F6lkt';
  if (code === 3) return '\u2601\uFE0F bedeckt';
  if (code === 45 || code === 48) return '\u{1F32B}\uFE0F Nebel';
  if (code >= 51 && code <= 57) return '\u{1F326}\uFE0F Nieselregen';
  if (code >= 61 && code <= 67) return '\u{1F327}\uFE0F Regen';
  if (code >= 71 && code <= 77) return '\u{1F328}\uFE0F Schnee';
  if (code >= 80 && code <= 82) return '\u{1F326}\uFE0F Schauer';
  if (code === 85 || code === 86) return '\u{1F328}\uFE0F Schneeschauer';
  if (code >= 95) return '\u26C8\uFE0F Gewitter';
  return '\u2753 unbekannt';
};
let wetter = '- Wetterdaten nicht abrufbar.';
try {
  const h = $('Wetter').first().json.hourly;
  const reihen = [6, 9, 12, 15, 18, 21].map((stunde) => {
    const regen = h.precipitation_probability[stunde];
    return `| ${String(stunde).padStart(2, '0')}:00 | ${WMO(h.weathercode[stunde])}${regen >= 30 ? ` (${regen} % Regen)` : ''} | ${Math.round(h.temperature_2m[stunde])} \u00B0C |`;
  });
  wetter = ['| Uhrzeit | Wetter | Temperatur |', '|---|---|---|', ...reihen].join('\n');
} catch (e) {
  wetter = '- Wetterdaten nicht abrufbar.';
}
const uhrzeit = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit' }).format(new Date());
const nachricht = [
  `#### \u2600\uFE0F Guten Morgen Peter \u2013 ${termine.datum}, ${uhrzeit} Uhr`,
  '##### 1. Termine heute',
  `${termine.termine}\n\n**HiOrg Kalender**\n${termine.hiorg}`,
  `**Wetter heute in Andernach**\n\n${wetter}`,
  `**Wochenschau (n\u00E4chste 7 Tage)**\n\n${termine.woche}`,
  '---',
  '##### 2. Sicherheitsl\u00FCcken und aktuelle Hacks',
  sicherheit,
  '---',
  '##### 3. Capulus-Core Health',
  daten.health,
  '---',
  '##### 4. News der Woche',
  woche,
].join('\n\n');
return [{ json: { nachricht: nachricht.slice(0, 11500) } }];
